    /**
     * Path "d" untuk satu ikon.
     *
     * Melempar exception kalau namanya salah supaya salah ketik ketahuan
     * seketika, bukan diam-diam menghasilkan kartu tanpa ikon.
     */
    public static function path(string $nama): string
    {
        return self::JALUR[$nama]
            ?? throw new InvalidArgumentException("Ikon \"{$nama}\" belum terdaftar di App\\Support\\Ikon.");
    }
